package com.citacloud.app.services; import com.citacloud.app.models.*; import com.citacloud.app.repositories.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class CheckInService {private final CheckInRepository checks;private final CitaRepository citas;public CheckInService(CheckInRepository c,CitaRepository ci){checks=c;citas=ci;}public List<CheckIn> listar(UUID empresa){return checks.findByEmpresaIdOrderByFechaHoraLlegadaDesc(empresa);}@Transactional public CheckIn registrar(UUID empresa,UUID usuario,UUID citaId){Cita cita=citas.findById(citaId).filter(c->empresa.equals(c.getEmpresaId())).orElseThrow(()->new IllegalArgumentException("Cita no encontrada para esta empresa."));if(!"CONFIRMADA".equals(cita.getEstado()))throw new IllegalArgumentException("Solo se puede registrar llegada de citas confirmadas.");if(checks.existsByEmpresaIdAndCitaId(empresa,citaId))throw new IllegalArgumentException("La llegada ya fue registrada.");CheckIn check=new CheckIn();check.setEmpresaId(empresa);check.setUsuarioId(usuario);check.setCita(cita);check.setPacienteId(cita.getPaciente().getId());cita.setEstado("EN_ESPERA");citas.save(cita);return checks.save(check);}}
